namespace SimplePZMapmaker.Core;
public static class WorldSeams
{
 public sealed record RepairResult(WorldProject World,int ChangedCells,string[] Issues);
 public static RepairResult Repair(WorldProject original,string mode="both"){
  WorldAssembler.Validate(original);if(mode is not("road" or "water" or "both"))throw new ArgumentException("Выберите дороги, реки или оба типа шва.");var world=WorldAssembler.Clone(original);var issues=new List<string>();var changed=0;
  var protectedCells=new HashSet<(int,int)>();foreach(var b in world.Buildings)foreach(var c in WorldAssembler.BuildingCells(b))protectedCells.Add(c);
  foreach(var member in world.Maps){var p=member.Project;foreach(var b in p.Buildings)foreach(var c in WorldAssembler.BuildingCells(b))protectedCells.Add((p.WorldX*256+c.X,p.WorldY*256+c.Y));foreach(var s in p.Spawns)protectedCells.Add((p.WorldX*256+s.X,p.WorldY*256+s.Y));foreach(var m in p.StaticModels)protectedCells.Add((p.WorldX*256+m.X,p.WorldY*256+m.Y));foreach(var d in p.Decorations)foreach(var part in d.Parts)protectedCells.Add((p.WorldX*256+d.X+part.Dx,p.WorldY*256+d.Y+part.Dy));}
  var masks=world.Maps.ToDictionary(m=>m.Id,m=>TerrainEditMask.Decode(m.Project));
  void Change(WorldMapMember member,int x,int y,Terrain terrain){var p=member.Project;if(x<0||y<0||x>=p.Width||y>=p.Height)return;var index=y*p.Width+x;if(p.Terrain[index]==terrain)return;var global=(p.WorldX*256+x,p.WorldY*256+y);if(protectedCells.Contains(global)||p.SurfaceTiles.ContainsKey(index)||TerrainEditMask.IsEdited(masks[member.Id],index)){if(issues.Count<64)issues.Add($"«{p.Name}»: клетка {global.Item1},{global.Item2} защищена объектом или ручной правкой покрытия.");return;}p.Terrain[index]=terrain;p.Version=6;masks[member.Id][index/8]|=(byte)(1<<(index%8));changed++;}
  void Join(WorldMapMember first,WorldMapMember second,bool vertical,int position){var a=first.Project;var b=second.Project;var ai=vertical?(position-a.WorldY*256)*a.Width+a.Width-1:(a.Height-1)*a.Width+position-a.WorldX*256;var bi=vertical?(position-b.WorldY*256)*b.Width:position-b.WorldX*256;var t=a.Terrain[ai];var u=b.Terrain[bi];if(t==u)return;var water=t==Terrain.Water||u==Terrain.Water;var road=t is Terrain.Road or Terrain.Pavement||u is Terrain.Road or Terrain.Pavement;if(water&&road){if(issues.Count<64)issues.Add($"«{a.Name}» / «{b.Name}»: вода встречается с дорогой у {position}; нужен мост или ручное решение.");return;}var target=water?Terrain.Water:t is Terrain.Road or Terrain.Pavement?t:u;if(water&&mode=="road"||!water&&(!road||mode=="water"))return;var scaleA=a.MetresPerTile??1;var scaleB=b.MetresPerTile??1;if(Math.Abs(scaleA-scaleB)>Math.Max(scaleA,scaleB)*.001){if(issues.Count<64)issues.Add("Разный масштаб: шов не переписывается.");return;}for(var depth=0;depth<3;depth++){if(vertical){Change(first,a.Width-1-depth,position-a.WorldY*256,target);Change(second,depth,position-b.WorldY*256,target);}else{Change(first,position-a.WorldX*256,a.Height-1-depth,target);Change(second,position-b.WorldX*256,depth,target);}}}
  for(var i=0;i<world.Maps.Count;i++)for(var j=i+1;j<world.Maps.Count;j++){var ma=world.Maps[i];var mb=world.Maps[j];var a=ma.Project;var b=mb.Project;var vertical=a.WorldX+a.Width/256==b.WorldX||b.WorldX+b.Width/256==a.WorldX;var horizontal=a.WorldY+a.Height/256==b.WorldY||b.WorldY+b.Height/256==a.WorldY;if(vertical){var left=a.WorldX<b.WorldX?ma:mb;var right=ReferenceEquals(left,ma)?mb:ma;for(var y=Math.Max(a.WorldY,b.WorldY)*256;y<Math.Min(a.WorldY+a.Height/256,b.WorldY+b.Height/256)*256;y++)Join(left,right,true,y);}if(horizontal){var top=a.WorldY<b.WorldY?ma:mb;var bottom=ReferenceEquals(top,ma)?mb:ma;for(var x=Math.Max(a.WorldX,b.WorldX)*256;x<Math.Min(a.WorldX+a.Width/256,b.WorldX+b.Width/256)*256;x++)Join(top,bottom,false,x);}}
  foreach(var m in world.Maps)if(m.Project.Version>=6)m.Project.TerrainEdits=TerrainEditMask.Encode(masks[m.Id]);WorldAssembler.Validate(world);return new(world,changed,issues.Distinct().ToArray());
 }
}
